try {
  const response = $input.first().json;
  const eventUrl = $('HTML to Markdown').first().json.url;

  // Check for API errors
  if (response.error) {
    return [{ json: { 
      error: true, 
      error_message: `OpenAI API error: ${response.error.message || 'Unknown error'}`,
      url: eventUrl 
    }}];
  }

  // Validate response structure
  if (!response.choices || !response.choices[0] || !response.choices[0].message) {
    return [{ json: { 
      error: true, 
      error_message: 'Invalid OpenAI response structure',
      url: eventUrl 
    }}];
  }

  let extracted;
  try {
    const content = response.choices[0].message.content;
    extracted = JSON.parse(content);
  } catch (e) {
    return [{ json: { 
      error: true, 
      error_message: `Failed to parse OpenAI JSON: ${e.message}`,
      url: eventUrl 
    }}];
  }

  // Return successfully extracted data
  return [{
    json: {
      error: false,
      url: eventUrl,
      title: extracted.title || 'Unknown Event',
      start_datetime: extracted.start_datetime || null,
      end_datetime: extracted.end_datetime || null,
      location: extracted.location || null,
      venue: extracted.venue || null,
      speakers: extracted.speakers || '',
      summary: extracted.summary || '',
      created_at: new Date().toISOString()
    }
  }];
} catch (error) {
  return [{ json: { 
    error: true, 
    error_message: `Unexpected error: ${error.message}`,
    url: eventUrl || 'unknown'
  }}];
}

try {
  const event = $('Parse OpenAI Response').first().json;
  const subscribers = $input.all().map(item => item.json);

  if (!event || !event.title) {
    throw new Error('Event data is missing or invalid');
  }

  if (!subscribers || subscribers.length === 0) {
    return []; // No subscribers, return empty
  }

  const speakersText = event.speakers || 'TBA';
  const title = event.title || 'Unnamed Event';
  const startDatetime = event.start_datetime;
  const endDatetime = event.end_datetime;
  const location = event.location || 'TBA';
  const venue = event.venue || '';
  const summary = event.summary || 'No summary available';
  const url = event.url || '#';

  // Format datetime for display
  const formatDateTime = (dt) => {
    if (!dt) return 'TBA';
    const d = new Date(dt);
    return d.toLocaleString('cs-CZ', { 
      weekday: 'long', 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  // Create iCalendar (ICS) content
  const formatICS = (dt) => {
    if (!dt) return '';
    return new Date(dt).toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z';
  };

  const icsContent = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//DataTalk//Event Scraper//EN',
    'CALSCALE:GREGORIAN',
    'METHOD:REQUEST',
    'BEGIN:VEVENT',
    `UID:${event.url}`,
    `DTSTART:${formatICS(startDatetime)}`,
    `DTEND:${formatICS(endDatetime)}`,
    `SUMMARY:${title}`,
    `DESCRIPTION:${summary.replace(/\n/g, '\\n')}`,
    `LOCATION:${location}${venue ? ', ' + venue : ''}`,
    `URL:${url}`,
    `ORGANIZER:${speakersText}`,
    'STATUS:CONFIRMED',
    'SEQUENCE:0',
    'END:VEVENT',
    'END:VCALENDAR'
  ].join('\r\n');

  const emailHtml = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
</head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; padding: 20px;">
  <div style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 30px; border-radius: 12px 12px 0 0; text-align: center;">
    <h1 style="margin: 0; font-size: 28px;">🎉 Nová akce na DataTalk!</h1>
  </div>

  <div style="background: #f8f9fa; padding: 30px; border-radius: 0 0 12px 12px;">
    <h2 style="color: #667eea; margin-top: 0;">${title}</h2>

    <div style="background: white; padding: 20px; border-radius: 8px; margin: 20px 0; border-left: 4px solid #667eea;">
      <p style="margin: 10px 0;"><strong>📅 Začíná:</strong> ${formatDateTime(startDatetime)}</p>
      <p style="margin: 10px 0;"><strong>⏰ Končí:</strong> ${formatDateTime(endDatetime)}</p>
      <p style="margin: 10px 0;"><strong>📍 Místo:</strong> ${location}${venue ? ' (' + venue + ')' : ''}</p>
      <p style="margin: 10px 0;"><strong>🎤 Přednášející:</strong> ${speakersText}</p>
    </div>

    <div style="background: white; padding: 20px; border-radius: 8px; margin: 20px 0;">
      <p style="color: #555;">${summary}</p>
    </div>

    <div style="text-align: center; margin: 30px 0;">
      <a href="${url}" style="display: inline-block; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 15px 40px; text-decoration: none; border-radius: 8px; font-weight: bold; font-size: 16px;">
        🔗 Více informací
      </a>
    </div>

    <p style="text-align: center; color: #888; font-size: 12px; margin-top: 30px;">
      📅 ICS soubor je přiložen - přidej si událost jedním kliknutím do kalendáře!
    </p>
  </div>
</body>
</html>
`;

  const telegramText = `🎤 *${title}*\n\n📅 ${formatDateTime(startDatetime)}\n📍 ${location}${venue ? ' (' + venue + ')' : ''}\n👤 ${speakersText}\n\n${summary}\n\n🔗 ${url}`;

  return subscribers.map(sub => ({
    json: {
      ...sub,
      event,
      emailHtml,
      telegramText,
      icsContent,
      icsFilename: `${title.replace(/[^a-z0-9]/gi, '_')}.ics`
    }
  }));
} catch (error) {
  throw new Error(`Notification preparation failed: ${error.message}`);
}
